arguments.command:
cd /work/submit && python3 - <<'EOF'
s = open('planb64.cpp').read()
old = """    bool next(std::string& line) {
        line.clear();
        terminated_ = false;
        for (;;) {
            if (pos_ < len_) {
                const char* base = buf_.data();
                const char* nl =
                    static_cast<const char*>(std::memchr(base + pos_, '\\n', len_ - pos_));
                if (nl != nullptr) {
                    size_t cut = static_cast<size_t>(nl - base);
                    append_bounded(line, base + pos_, cut - pos_);
                    pos_ = cut + 1;
                    terminated_ = true;
                    return true;
                }
                append_bounded(line, base + pos_, len_ - pos_);
                pos_ = len_;
            }
            ssize_t r = ::read(fd_, buf_.data(), buf_.size());
            if (r < 0) {
                if (errno == EINTR) continue;
                fail("read error on " + quote(path_) + ": " + std::string(std::strerror(errno)));
            }
            if (r == 0) return !line.empty();
            pos_ = 0;
            len_ = static_cast<size_t>(r);
        }
    }

    bool terminated() const { return terminated_; }"""
new = """    // Delivers the next line (without its '\\n').  Returns false once the whole
    // stream has been consumed.  terminated() reports whether the most recently
    // delivered line ended with a newline.
    bool next(std::string& line) {
        line.clear();
        for (;;) {
            if (pos_ < len_) {
                const char* base = buf_.data();
                const char* nl =
                    static_cast<const char*>(std::memchr(base + pos_, '\\n', len_ - pos_));
                if (nl != nullptr) {
                    const size_t cut = static_cast<size_t>(nl - base);
                    append_bounded(line, base + pos_, cut - pos_);
                    pos_ = cut + 1;
                    last_terminated_ = true;
                    return true;
                }
                append_bounded(line, base + pos_, len_ - pos_);
                pos_ = len_;
            }
            ssize_t r = ::read(fd_, buf_.data(), buf_.size());
            if (r < 0) {
                if (errno == EINTR) continue;
                fail("read error on " + quote(path_) + ": " + std::string(std::strerror(errno)));
            }
            if (r == 0) {
                if (line.empty()) return false;  // keeps terminated() untouched
                last_terminated_ = false;        // final line without newline
                return true;
            }
            pos_ = 0;
            len_ = static_cast<size_t>(r);
        }
    }

    bool terminated() const { return last_terminated_; }"""
assert old in s
s = s.replace(old, new)
s = s.replace("""    int fd_ = -1;
    bool terminated_ = false;""", """    int fd_ = -1;
    bool last_terminated_ = false;""")
open('planb64.cpp','w').write(s)
EOF
make clean >/dev/null && make 2>&1|tail -3
cd /work && for m in "scalar" "batch 3" "batch 003" "batch 1" "batch 256" "batch 9"; do /work/submit/planb64 lookup /work/example.idx /work/examples/trace.txt $m > /tmp/o.txt 2>/tmp/e.txt; rc=$?; if diff -q /tmp/o.txt /work/examples/expected.txt >/dev/null && [ ! -s /tmp/e.txt ]; then echo "$m OK"; else echo "$m FAIL rc=$rc"; cat /tmp/o.txt /tmp/e.txt; fi; done
